'use client'

import { useState, useCallback } from 'react'
import { useEditorStore } from '../store/editor-store'
import { DEMOLAR } from '@/data/demoVitrinData'

export default function RightPanel() {
    const siteData = useEditorStore(s => s.siteData)
    const updateSiteData = useEditorStore(s => s.updateSiteData)
    const rightPanelOpen = useEditorStore(s => s.rightPanelOpen)
    const setRightPanelOpen = useEditorStore(s => s.setRightPanelOpen)

    const [activeTab, setActiveTab] = useState<'genel' | 'icerik' | 'tasarim'>('genel')

    if (!rightPanelOpen || !siteData) return null

    return (
        <>
            <style>{`
                .ke-rp { width: 320px; background: #fff; border-left: 1px solid #e2e8f0; display: flex; flex-direction: column; flex-shrink: 0; animation: keSlideLeft 0.2s ease-out; overflow: hidden; }
                @keyframes keSlideLeft { from { opacity: 0; transform: translateX(8px); } to { opacity: 1; transform: none; } }
                .ke-rp-head { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; border-bottom: 1px solid #e8ecf1; background: #fafbfc; }
                .ke-rp-title { font-size: 14px; font-weight: 700; color: #17191c; display: flex; align-items: center; gap: 8px; }
                .ke-rp-close { width: 28px; height: 28px; border: none; background: transparent; cursor: pointer; border-radius: 6px; display: flex; align-items: center; justify-content: center; color: #94a3b8; transition: 0.15s; }
                .ke-rp-close:hover { background: #f1f5f9; color: #17191c; }

                .ke-rp-tabs { display: flex; border-bottom: 1px solid #e8ecf1; background: #fff; }
                .ke-rp-tab { flex: 1; padding: 10px; text-align: center; font-size: 12px; font-weight: 600; color: #64748b; cursor: pointer; border-bottom: 2px solid transparent; transition: 0.15s; font-family: inherit; background: none; border-left: none; border-right: none; border-top: none; }
                .ke-rp-tab:hover { color: #334155; background: #f8fafc; }
                .ke-rp-tab.active { color: #2563eb; border-bottom-color: #2563eb; }

                .ke-rp-body { flex: 1; overflow-y: auto; padding: 16px; }

                .ke-field { margin-bottom: 18px; }
                .ke-label { font-size: 11px; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.04em; margin-bottom: 6px; display: flex; align-items: center; justify-content: space-between; }
                .ke-input { width: 100%; padding: 9px 12px; border: 1px solid #e2e8f0; border-radius: 8px; font-size: 13px; color: #17191c; font-family: inherit; transition: 0.15s; outline: none; background: #f8fafc; box-sizing: border-box; }
                .ke-input:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59,130,246,0.08); background: #fff; }
                .ke-textarea { resize: vertical; min-height: 72px; }

                .ke-color-row { display: flex; gap: 6px; flex-wrap: wrap; }
                .ke-color-swatch { width: 28px; height: 28px; border-radius: 6px; cursor: pointer; border: 2px solid #e2e8f0; transition: 0.15s; }
                .ke-color-swatch:hover { transform: scale(1.15); }
                .ke-color-swatch.active { border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59,130,246,0.2); }

                .ke-divider { height: 1px; background: #e8ecf1; margin: 16px 0; }

                .ke-sector-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border: 1px solid #e2e8f0; border-radius: 8px; font-size: 12px; font-weight: 600; color: #334155; cursor: pointer; transition: 0.15s; background: #f8fafc; font-family: inherit; }
                .ke-sector-chip:hover { background: #eff6ff; border-color: #93c5fd; }
                .ke-sector-chip.active { background: #dbeafe; border-color: #3b82f6; color: #1e40af; }

                .ke-hizmet-row { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
                .ke-hizmet-row input { flex: 1; }
                .ke-hizmet-idx { width: 20px; height: 20px; background: #f1f5f9; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 800; color: #94a3b8; flex-shrink: 0; }

                .ke-font-select { width: 100%; padding: 9px 12px; border: 1px solid #e2e8f0; border-radius: 8px; font-size: 13px; color: #17191c; font-family: inherit; outline: none; background: #f8fafc; cursor: pointer; }
                .ke-font-select:focus { border-color: #3b82f6; }

                .ke-info-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px; margin-bottom: 12px; }
                .ke-info-label { font-size: 10px; font-weight: 700; color: #94a3b8; text-transform: uppercase; margin-bottom: 4px; }
                .ke-info-value { font-size: 13px; font-weight: 600; color: #334155; }
            `}</style>

            <div className="ke-rp">
                <div className="ke-rp-head">
                    <span className="ke-rp-title">✏️ Site Düzenle</span>
                    <button className="ke-rp-close" onClick={() => setRightPanelOpen(false)}>
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
                    </button>
                </div>

                <div className="ke-rp-tabs">
                    <button className={`ke-rp-tab${activeTab === 'genel' ? ' active' : ''}`} onClick={() => setActiveTab('genel')}>Genel</button>
                    <button className={`ke-rp-tab${activeTab === 'icerik' ? ' active' : ''}`} onClick={() => setActiveTab('icerik')}>İçerik</button>
                    <button className={`ke-rp-tab${activeTab === 'tasarim' ? ' active' : ''}`} onClick={() => setActiveTab('tasarim')}>Tasarım</button>
                </div>

                <div className="ke-rp-body">
                    {activeTab === 'genel' && <GenelTab />}
                    {activeTab === 'icerik' && <IcerikTab />}
                    {activeTab === 'tasarim' && <TasarimTab />}
                </div>
            </div>
        </>
    )
}

/* ═══════ Genel Tab ═══════ */
function GenelTab() {
    const siteData = useEditorStore(s => s.siteData)!
    const updateSiteData = useEditorStore(s => s.updateSiteData)

    return (
        <div>
            <div className="ke-info-card">
                <div className="ke-info-label">Sektör</div>
                <div className="ke-info-value">{DEMOLAR.find(d => d.id === siteData.sektorId)?.ad || 'Bilinmiyor'}</div>
            </div>
            <div className="ke-info-card">
                <div className="ke-info-label">Paket</div>
                <div className="ke-info-value">{siteData.paket}</div>
            </div>

            <div className="ke-divider" />

            <div className="ke-field">
                <div className="ke-label">İşletme Adı</div>
                <input className="ke-input" value={siteData.isletmeAdi} onChange={e => updateSiteData({ isletmeAdi: e.target.value, heroBaslik: e.target.value })} placeholder="İşletme adınız…" />
            </div>

            <div className="ke-field">
                <div className="ke-label">Telefon</div>
                <input className="ke-input" value={siteData.telefon} onChange={e => updateSiteData({ telefon: e.target.value })} placeholder="05XX XXX XX XX" />
            </div>

            <div className="ke-field">
                <div className="ke-label">Adres</div>
                <input className="ke-input" value={siteData.adres} onChange={e => updateSiteData({ adres: e.target.value })} placeholder="İlçe, Şehir" />
            </div>

            <div className="ke-divider" />

            <div className="ke-field">
                <div className="ke-label">Sektör Değiştir</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px', maxHeight: '200px', overflowY: 'auto' }}>
                    {DEMOLAR.slice(0, 20).map(d => (
                        <button
                            key={d.id}
                            className={`ke-sector-chip${siteData.sektorId === d.id ? ' active' : ''}`}
                            onClick={() => updateSiteData({
                                sektorId: d.id,
                                kategori: d.kategori,
                                heroAlt: d.heroAlt,
                                hizmetler: d.hizmetler,
                                bg: d.bg,
                                accent: d.accent,
                                text: d.text,
                                font: d.font,
                                unsplash: d.unsplash,
                            })}
                        >
                            {d.ad}
                        </button>
                    ))}
                </div>
            </div>
        </div>
    )
}

/* ═══════ İçerik Tab ═══════ */
function IcerikTab() {
    const siteData = useEditorStore(s => s.siteData)!
    const updateSiteData = useEditorStore(s => s.updateSiteData)

    const updateHizmet = useCallback((index: number, value: string) => {
        const h = [...siteData.hizmetler] as [string, string, string]
        h[index] = value
        updateSiteData({ hizmetler: h })
    }, [siteData.hizmetler, updateSiteData])

    return (
        <div>
            <div className="ke-field">
                <div className="ke-label">Hero Başlık</div>
                <input className="ke-input" value={siteData.heroBaslik} onChange={e => updateSiteData({ heroBaslik: e.target.value })} placeholder="Ana başlık…" />
            </div>

            <div className="ke-field">
                <div className="ke-label">Alt Başlık</div>
                <input className="ke-input" value={siteData.heroAlt} onChange={e => updateSiteData({ heroAlt: e.target.value })} placeholder="Alt başlık…" />
            </div>

            <div className="ke-divider" />

            <div className="ke-field">
                <div className="ke-label">Hizmetler</div>
                {siteData.hizmetler.map((h, i) => (
                    <div key={i} className="ke-hizmet-row">
                        <div className="ke-hizmet-idx">{i + 1}</div>
                        <input className="ke-input" value={h} onChange={e => updateHizmet(i, e.target.value)} placeholder={`Hizmet ${i + 1}`} />
                    </div>
                ))}
            </div>
        </div>
    )
}

/* ═══════ Tasarım Tab ═══════ */
function TasarimTab() {
    const siteData = useEditorStore(s => s.siteData)!
    const updateSiteData = useEditorStore(s => s.updateSiteData)

    const BG_COLORS = ['#0f172a', '#1e293b', '#0d0d0d', '#111111', '#0a0a0f', '#0b1929', '#1a0f05', '#faf4ed', '#fffdf7', '#f8f5f0', '#f5f4f0', '#f0f8ff', '#f1fffe', '#f0f4ff', '#ffffff']
    const ACCENT_COLORS = ['#c2440e', '#c2773a', '#e8a030', '#b8960c', '#d4709a', '#c9856a', '#c53030', '#2e86de', '#e63946', '#f5a623', '#8b6f47', '#c9a84c', '#7c3aed', '#4f46e5', '#00c9a7', '#10b981', '#00897b', '#ff3c00', '#ff6b35']
    const FONTS = ['Cormorant Garamond', 'Playfair Display', 'Abril Fatface', 'Bebas Neue', 'Syne', 'Inter', 'Outfit', 'Raleway', 'Montserrat', 'Poppins', 'Nunito', 'Space Grotesk', 'Oswald', 'Anton', 'Lora', 'Fraunces']

    return (
        <div>
            <div className="ke-field">
                <div className="ke-label">Arkaplan Rengi</div>
                <div className="ke-color-row">
                    {BG_COLORS.map(c => (
                        <div key={c} className={`ke-color-swatch${siteData.bg === c ? ' active' : ''}`} style={{ background: c }} onClick={() => updateSiteData({ bg: c })} />
                    ))}
                </div>
            </div>

            <div className="ke-field">
                <div className="ke-label">Vurgu Rengi</div>
                <div className="ke-color-row">
                    {ACCENT_COLORS.map(c => (
                        <div key={c} className={`ke-color-swatch${siteData.accent === c ? ' active' : ''}`} style={{ background: c }} onClick={() => updateSiteData({ accent: c })} />
                    ))}
                </div>
            </div>

            <div className="ke-divider" />

            <div className="ke-field">
                <div className="ke-label">Yazı Tipi</div>
                <select className="ke-font-select" value={siteData.font} onChange={e => updateSiteData({ font: e.target.value })}>
                    {FONTS.map(f => (
                        <option key={f} value={f}>{f}</option>
                    ))}
                </select>
            </div>
        </div>
    )
}
